<script lang="ts">
	// Throwaway: three spend-first layouts on /?variant=A|B|C, with fictional data.
	import { page } from '$app/state';
	import { goto } from '$app/navigation';
	import BrandMark from '$lib/components/ds/BrandMark.svelte';
	import MoneyFigure from '$lib/components/ds/MoneyFigure.svelte';
	import { accounts as allAccounts, selectUsage } from '$lib/components/prototype-data';
	import { flourishFor, formatFlourishText, DAILY_FLOURISHES, LIFETIME_FLOURISHES, BLOCK_FLOURISHES } from '$lib/voice';
	import PrototypeSwitcher from '$lib/components/PrototypeSwitcher.svelte';
	let variant = $derived(page.url.searchParams.get('variant') ?? 'A');
	let scene = $derived(page.url.searchParams.get('state') ?? 'overview');
	let section = $state('Dashboard');
	let period = $state('30 days');
	let selected = $state(0);
	let detailDialog = $state<HTMLDialogElement>();
	$effect(() => {
		if (!detailDialog) return;
		if (scene === 'detail' && !detailDialog.open) detailDialog.showModal();
		else if (scene !== 'detail' && detailDialog.open) detailDialog.close();
	});
	let provider = $state('all');
	let machine = $state('all');
	let accountId = $state('all');
	let hoveredDay = $state<number | null>(null);
	const usage = $derived(selectUsage(provider, machine, accountId));
	const accounts = $derived(usage.accounts);
	const sessions = $derived(usage.entries.filter(entry => entry.day < 30).toSorted((a,b) => b.cost-a.cost));
	const detail = $derived(sessions[selected] ?? sessions[0]);
	const fees = $derived(accounts.reduce((sum,account) => sum + account.monthlyUsd, 0));
	const windows = $derived([
		{ label: 'All time', value: usage.totals.all, remark: formatFlourishText(flourishFor(usage.totals.all,LIFETIME_FLOURISHES)) },
		{ label: 'Today', value: usage.totals.today, remark: formatFlourishText(flourishFor(usage.totals.today,DAILY_FLOURISHES)) },
		{ label: '7 days', value: usage.totals.week, remark: '' },
		{ label: '30 days', value: usage.totals.month, remark: '' }
	]);
	const chartMax = $derived(Math.max(1, ...usage.days30));
	const providerTotals = $derived(['Claude','Codex'].map(name => ({ name, value: usage.entries.filter(e => e.day < 30 && allAccounts.find(a => a.id === e.accountId)?.provider === name).reduce((sum,e)=>sum+e.cost,0) })));
	function money(value: number) { return value.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}); }
	function dayLabel(index: number) { return new Date(Date.UTC(2026,7,12+index)).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}); }
	function clearFilters() { provider='all'; machine='all'; accountId='all'; }
	function setParam(key: string, value: string) {
		const url = new URL(page.url); url.searchParams.set(key, value);
		void goto(url, { replaceState: true, noScroll: true, keepFocus: true });
	}
	function openSession(index: number) { selected = index; setParam('state', 'detail'); }
</script>

<svelte:head><title>chaching · Dashboard layout prototype</title><meta name="robots" content="noindex" /></svelte:head>

{#snippet quota(account: typeof accounts[number], compact = false)}
	<div class:compact class="quota-pair">
		{#each [{label: 'Short term', value: account.short, reset: account.reset}, {label: 'Weekly', value: account.week, reset: account.weeklyReset}] as q}
			<div class="quota-window" class:low={q.value < 25}>
				<div class="window-label"><span>{q.label}</span><span class="remaining"><b>{q.value}%</b> left</span></div>
				<meter min="0" max="100" value={q.value} aria-label={`${account.name} ${q.label} quota remaining`}></meter>
				<small>Resets {q.reset}</small>
			</div>
		{/each}
	</div>
{/snippet}

{#snippet accountName(account: typeof accounts[number])}
	<div class="account-name"><strong>{account.name}</strong><span>{account.plan}</span></div>
	{#if account.activeMachines.some(m => machine === 'all' || machine === m)}<span class="active">Current on {account.activeMachines.filter(m => machine === 'all' || machine === m).join(', ')}</span>{:else}<span class="available">Available</span>{/if}
{/snippet}

<div class="prototype" class:ledger={variant === 'B'} class:lanes={variant === 'C'}>
	<div class="sample">DESIGN PROTOTYPE <span>Fictional data · Thu 10 Sep, 16:00 UTC</span></div>
	<header><BrandMark wordmark size={18}/><nav aria-label="Main navigation">{#each ['Dashboard', 'Explore usage', 'Settings'] as item}<button class:chosen={section === item} onclick={() => section = item}>{item}</button>{/each}</nav><select class="compact-nav" aria-label="View" bind:value={section}><option>Dashboard</option><option>Explore usage</option><option>Settings</option></select><span class="machine">MacBook</span></header>
	<main>
		{#if scene === 'loading'}
			<section class="cold" aria-live="polite"><h1>Counting your sins…</h1><p>Cold-scanning Claude Code transcripts.</p><div class="scan-line"></div><p class="muted">First load streams every session file once.<br/>This is the only slow part.</p><button onclick={() => setParam('state','overview')}>Preview loaded dashboard →</button></section>
		{:else if section === 'Settings'}
			<div class="page-title"><div><h1>Settings</h1></div><span>Preview only</span></div>
			<section class="settings"><h2>Accounts</h2>{#each allAccounts as account}<div class="settings-row">{@render accountName(account)}<span>$200 / month</span></div>{/each}<h2>Sync</h2><p>MacBook · this machine</p><p class="muted">Account editing and pool setup live here. This prototype does not change your settings.</p></section>
		{:else if section === 'Explore usage'}
			<div class="page-title"><div><h1>Explore usage</h1></div><button onclick={() => section = 'Dashboard'}>Back to dashboard</button></div>
			<section class="explore"><h2>September activity</h2><div class="heatmap" aria-label="Fictional daily activity">{#each Array.from({length: 70}, (_, i) => i) as day}<button aria-label={`Preview day ${day + 1}`} style:opacity={0.2 + ((day * 7) % 9) / 12} onclick={() => openSession(0)}></button>{/each}</div><div class="breakdowns">{#each [{title: 'By model', rows: ['Fable 5.1', 'GPT-6 Astra']}, {title: 'By project', rows: ['rennet', 'chaching']}] as group}<section><h2>{group.title}</h2>{#each group.rows as row,i}<div class="breakdown"><span>{row}</span><meter aria-label={`${row} share`} min="0" max="100" value={i ? 38 : 62}></meter><b>{i ? '38' : '62'}%</b></div>{/each}</section>{/each}</div><h2>Sessions</h2>{@render sessionList()}</section>
		{:else}
			<h1 class="sr-only">Dashboard</h1>
			<div class="filters" aria-label="Usage filters">
				<label><span>Provider</span><select aria-label="Provider" bind:value={provider}><option value="all">All providers</option><option>Claude</option><option>Codex</option></select></label>
				<label><span>Machine</span><select aria-label="Machine" bind:value={machine}><option value="all">All machines</option><option>MacBook</option><option>Mac mini</option></select></label>
				<label><span>Account</span><select aria-label="Account" bind:value={accountId}><option value="all">All Accounts</option>{#each allAccounts as account}<option value={account.id}>{account.name}</option>{/each}</select></label>
				{#if provider !== 'all' || machine !== 'all' || accountId !== 'all'}<button onclick={clearFilters}>Clear filters</button>{/if}
			</div>
			<section class="spend" aria-label="Spend overview">{#each windows as stat}<div><span class="eyebrow">{stat.label}</span><MoneyFigure amount={stat.value} size="hero" animate={false}/><small class="flavour">{stat.remark || '\u00a0'}</small></div>{/each}</section>
			<div class="charts">
				<section class="daily-chart"><div class="section-heading"><h2>Daily spend</h2><span>{hoveredDay === null ? 'Last 30 days' : `${dayLabel(hoveredDay)} · ${money(usage.days30[hoveredDay])}`}</span></div>
				<div class="plot"><div class="axis"><span>{money(chartMax)}</span><span>{money(chartMax/2)}</span><span>$0</span></div><div class="bars">{#each usage.days30 as value,i}<button class:bar-selected={hoveredDay === i} style:--bar-height={`${value/chartMax*100}%`} onmouseenter={() => hoveredDay=i} onmouseleave={() => hoveredDay=null} onfocus={() => hoveredDay=i} onblur={() => hoveredDay=null} aria-label={`${dayLabel(i)}: ${money(value)}`} title={`${dayLabel(i)}: ${money(value)}`}><span></span></button>{/each}</div></div><div class="dates"><span>12 Aug</span><span>26 Aug</span><span>10 Sep</span></div>
				</section>
				<section class="provider-chart"><div class="section-heading"><h2>By provider</h2><span>30 days</span></div>{#each providerTotals as entry}<div class="provider-total"><div><span>{entry.name}</span><strong>{money(entry.value)}</strong></div><meter min="0" max={Math.max(1,usage.totals.month)} value={entry.value} aria-label={`${entry.name} spend: ${money(entry.value)}`}></meter></div>{/each}</section>
			</div>

			<section class="quota-section" aria-label="Account quotas">
				{#if accounts.length === 0}<p class="empty">No Accounts match these filters. <button onclick={clearFilters}>Clear filters</button></p>{/if}
				{#if variant === 'A'}
					<div class="section-heading"><h2>Current Accounts</h2><span>Remaining allowance</span></div>
					<div class="current-focus">{#each accounts.filter(a => a.activeMachines.some(m => machine === 'all' || machine === m)) as account}<article class:attention={account.short < 25}><div class="account-top">{@render accountName(account)}</div>{@render quota(account)}</article>{/each}</div>
					{#each accounts.filter(a => !a.activeMachines.some(m => machine === 'all' || machine === m)) as account}<div class="other-account"><div><span class="eyebrow">Also available</span><strong>{account.name} <small>{account.plan}</small></strong></div>{@render quota(account, true)}</div>{/each}

				{:else if variant === 'B'}
					<div class="section-heading"><h2>All Accounts</h2><span>Most constrained first · remaining allowance</span></div>
					<div class="ledger-head"><span>Account / plan</span><span>Short term</span><span>Weekly</span></div>
					{#each [...accounts].sort((a,b) => Math.min(a.short,a.week)-Math.min(b.short,b.week)) as account}<article class="ledger-row"><div>{@render accountName(account)}</div>{@render quota(account)}</article>{/each}
				{:else}
					<div class="provider-lanes">{#each ['Claude','Codex'].filter(p => accounts.some(a => a.provider===p)) as provider}<section class="provider-lane"><div class="provider-title"><h2>{provider}</h2><span>{accounts.filter(a=>a.provider===provider).length} {accounts.filter(a=>a.provider===provider).length === 1 ? 'Account' : 'Accounts'}</span></div>{#each accounts.filter(a=>a.provider===provider) as account}<article><div class="account-top">{@render accountName(account)}</div>{@render quota(account)}</article>{/each}</section>{/each}</div>
				{/if}
			</section>
			
			<div class="lower">
				<div class="reading-column"><section class="block"><div class="section-heading"><h2>Five-hour spend block</h2><span>This MacBook only</span></div><div class="block-value"><MoneyFigure amount={142.68} size="lg" tone="gold" animate={false}/><span>13:00–18:00 UTC<br/>2h remaining</span></div><div class="ticks" aria-label="Three of five hours elapsed">{#each Array.from({length: 30},(_,i)=>i) as tick}<i class:elapsed={tick < 18}></i>{/each}</div><p class="block-flavour">{formatFlourishText(flourishFor(142.68,BLOCK_FLOURISHES))}</p></section>
				<section class="sessions"><div class="section-heading"><h2>Most expensive sessions</h2><button onclick={() => section = 'Explore usage'}>View all →</button></div>{@render sessionList()}</section></div>
				<aside class="receipt"><div class="section-heading"><h2>Subsidisation</h2><label>Period <select bind:value={period}><option>30 days</option></select></label></div><div class="multiplier">{fees ? (usage.totals.month/fees).toFixed(1) : '—'}{#if fees}<span>×</span>{/if}</div><p>API value across {accounts.length} {accounts.length === 1 ? 'Account' : 'Accounts'}</p><dl><div><dt>Usage value</dt><dd>{money(usage.totals.month)}</dd></div><div><dt>Account fees</dt><dd>{money(fees)}</dd></div><div class="net"><dt>Difference</dt><dd>{money(usage.totals.month-fees)}</dd></div></dl><div class="average"><span>Average $/hour</span><b>{money(usage.totals.month/712)}</b></div><small>12 Aug–10 Sep 2026<br/>30 days ending today · 712 elapsed hours</small></aside>
			</div>
		{/if}
	</main>
	
</div>

{#snippet sessionList()}
	<div class="session-list">{#each (section === 'Explore usage' ? sessions : sessions.slice(0,5)) as session, i}<button class="session" onclick={() => openSession(i)}><span class="rank">0{i+1}</span><span class="session-name"><strong>{session.name}</strong><small>{session.project} · {session.model}</small></span><span class="session-cost">${session.cost.toFixed(2)}<small>{session.time}</small></span><span aria-hidden="true">↗</span></button>{/each}</div>
{/snippet}

{#if detail}<dialog bind:this={detailDialog} oncancel={() => setParam('state','overview')} aria-labelledby="detail-title">
	<div class="detail-head"><span class="eyebrow">Session receipt · fictional data</span><button aria-label="Close session detail" onclick={() => setParam('state','overview')}>×</button></div><h2 id="detail-title">{detail.name}</h2><p>{detail.project} · {detail.model}</p><MoneyFigure amount={detail.cost} size="hero" animate={false}/><dl><div><dt>Tokens</dt><dd>{detail.tokens}</dd></div><div><dt>Started</dt><dd>{detail.time}</dd></div><div><dt>Machine</dt><dd>{detail.machine}</dd></div></dl><button onclick={() => setParam('state','overview')}>Back to dashboard</button>
</dialog>{/if}
<PrototypeSwitcher {variant} onchange={v => setParam('variant',v)} state={scene} onstate={s => setParam('state',s)}/>

