	nav button{color:var(--text-muted)}nav button.chosen{color:var(--text);box-shadow:0 2px var(--accent)}.machine{margin-left:auto;font:var(--type-label);color:var(--text-muted)}
	main{padding:28px 0 160px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.page-title{display:flex;justify-content:space-between;align-items:end;margin-bottom:32px;gap:20px}.eyebrow{display:block;font:var(--type-label);letter-spacing:.08em;text-transform:uppercase;color:var(--text-muted)}h1{font:var(--type-display);letter-spacing:-.045em;margin:10px 0 0}h2{font:var(--type-title);margin:0}.page-title>span{font:var(--type-label);color:var(--text-muted);padding-bottom:6px}.section-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}.section-heading>span,.section-heading label{font:var(--type-label);color:var(--text-muted)}.section-heading h2{font-size:var(--text-lg)}
	.current-focus{display:grid;grid-template-columns:1.2fr 1fr;border:1px solid var(--border)}.current-focus article{padding:24px 28px}.current-focus article+article{border-left:1px solid var(--border)}.current-focus article.attention{background:var(--accent-soft);border-top:3px solid var(--accent);padding-top:21px}.account-top{display:flex;align-items:start;justify-content:space-between;gap:16px}.account-name{display:flex;flex-direction:column;gap:3px}.account-name strong{font-size:var(--text-lg)}.account-name span,.available{font-size:var(--text-xs);color:var(--text-muted)}.active{font:var(--type-label);color:var(--accent);padding-top:5px}.quota-pair{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:30px}.window-label{display:flex;justify-content:space-between;align-items:baseline;gap:10px;font-size:var(--text-sm)}.remaining{font-size:var(--text-xs);color:var(--text-muted)}.remaining b{font:700 30px/1.2 var(--font-num);color:var(--text)}.low .remaining b{color:var(--accent)}meter{display:block;width:100%;height:7px;appearance:none;border:0;margin:12px 0;background:var(--border);border-radius:0}meter::-webkit-meter-bar{background:var(--border);border:0;border-radius:0;height:7px}meter::-webkit-meter-optimum-value{background:var(--paper-200)}.low meter::-webkit-meter-optimum-value{background:var(--accent)}meter::-moz-meter-bar{background:var(--paper-200)}small{font-size:var(--text-xs);color:var(--text-muted)}
